package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;

public class Element_clone_TriageGen1Test {

    @Test
    public void testClone_NoClasses() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "baseUri", new Attributes());
        // Act
        Element clone = element.clone();
        // Assert
        assertEquals(element, clone);
        assertNotSame(element, clone);
    }

    @Test
    public void testClone_WithClass() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "baseUri", new Attributes().attr("class", "test"));
        // Act
        Element clone = element.clone();
        // Assert
        assertEquals(element, clone);
        assertNotSame(element, clone);
    }

    @Test
    public void testClone_SuperClone() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "baseUri", new Attributes());
        Element superClone = (Element) element.clone();
        // Act
        Element clone = element.clone();
        // Assert
        assertNotSame(superClone, clone);
        assertEquals(element, clone);
    }

    @Test
    public void testClone_NullElement() {
        // Act and Assert
        try {
            Element element = null;
            element.clone();
            assert false;
        } catch (NullPointerException e) {
            assert true;
        }
    }

    @Test
    public void testClone_ClassNamesCalledOnClone() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "baseUri", new Attributes());
        // Act
        element.clone();
        // Assert
        // This is a bit tricky since we are testing if a method is called. We can use Mockito to verify this.
        // However, since the class is final, we cannot use Mockito. So we will just assert that the method is called.
        // This can be done by checking if the attributes are present in the clone.
        Element clone = element.clone();
        assert (clone.attributes().hasKey("class"));
    }

    @Test
    public void testClone_ClassNamesCalledOnCloneTwice() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "baseUri", new Attributes());
        // Act
        element.clone().clone();
        // Assert
        Element clone = element.clone();
        assert (clone.attributes().hasKey("class"));
    }
}
